        "Forme: strömt aus, strömte aus. Când ceva iese și există mișcare, auxiliarul la perfectul compus este sein: Das Gas ist ausgeströmt. Cu un complement direct la acuzativ (Ruhe ausströmen) se folosește haben: Sie hat Ruhe ausgeströmt.",
        "Cuvântul este apropiat de strömen (a curge). Cele mai frecvente utilizări sunt cele tehnice, despre scurgeri de gaz, și cele figurate, despre impresia pe care o lasă un om."
