        "Forme: beschränkt sich, beschränkte sich, hat sich beschränkt. Prefixul be- este inseparabil, de aceea nu apare ge-.",
        "Fără sich, beschränken înseamnă a limita altceva: die Zahl beschränken. Despre lucruri care se rezumă la ceva se folosește sich beschränken auf: Das Problem beschränkt sich auf …"
